import { asBytes, asNumber, asOptionalString, asString } from 'zapo-js/util';
import { BaseSqliteStore } from './BaseSqliteStore.js';
const DEFAULT_RETRY_TTL_MS = 60 * 1000;
function isObjectRecord(value) {
    return !!value && typeof value === 'object' && !Array.isArray(value);
}
export class WaRetrySqliteStore extends BaseSqliteStore {
    constructor(options, ttlMs = DEFAULT_RETRY_TTL_MS) {
        super(options, ['retry']);
        if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
            throw new Error('retry ttlMs must be a positive finite number');
        }
        this.ttlMs = ttlMs;
    }
    getTtlMs() {
        return this.ttlMs;
    }
    supportsRawReplayPayload() {
        return false;
    }
    async getOutboundRequesterStatus(messageId, requesterDeviceJid) {
        const db = await this.getConnection();
        const row = db.get(`SELECT requesters_json
             FROM retry_outbound_messages
             WHERE session_id = ? AND message_id = ?
             LIMIT 1`, [this.options.sessionId, messageId]);
        if (!row) {
            return null;
        }
        const requestersJson = asOptionalString(row.requesters_json, 'retry_outbound_messages.requesters_json');
        if (!requestersJson) {
            return null;
        }
        const requesters = this.parseRequesterStatusPayload(requestersJson);
        if (requesters.eligible.length === 0) {
            return null;
        }
        let isEligible = false;
        for (let index = 0; index < requesters.eligible.length; index += 1) {
            if (requesters.eligible[index] === requesterDeviceJid) {
                isEligible = true;
                break;
            }
        }
        if (!isEligible) {
            return {
                eligible: false,
                delivered: false
            };
        }
        for (let index = 0; index < requesters.delivered.length; index += 1) {
            if (requesters.delivered[index] === requesterDeviceJid) {
                return {
                    eligible: true,
                    delivered: true
                };
            }
        }
        return {
            eligible: true,
            delivered: false
        };
    }
    async upsertOutboundMessage(record) {
        const requestersJson = this.serializeRequesterStatusPayload(record.eligibleRequesterDeviceJids, record.deliveredRequesterDeviceJids);
        if (!(record.replayPayload instanceof Uint8Array)) {
            throw new Error('retry_outbound_messages.replay_payload must be Uint8Array');
        }
        const replayPayload = record.replayPayload;
        const db = await this.getConnection();
        db.run(`INSERT INTO retry_outbound_messages (
                session_id,
                message_id,
                to_jid,
                replay_mode,
                replay_payload,
                requesters_json,
                state,
                updated_at_ms,
                expires_at_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id, message_id) DO UPDATE SET
                to_jid=excluded.to_jid,
                replay_mode=excluded.replay_mode,
                replay_payload=excluded.replay_payload,
                requesters_json=excluded.requesters_json,
                state=excluded.state,
                updated_at_ms=excluded.updated_at_ms,
                expires_at_ms=excluded.expires_at_ms`, [
            this.options.sessionId,
            record.messageId,
            record.toJid,
            record.replayMode,
            replayPayload,
            requestersJson,
            record.state,
            record.updatedAtMs,
            record.expiresAtMs
        ]);
    }
    async deleteOutboundMessage(messageId) {
        const db = await this.getConnection();
        db.run(`DELETE FROM retry_outbound_messages
             WHERE session_id = ? AND message_id = ?`, [this.options.sessionId, messageId]);
        const row = db.get('SELECT changes() AS total', []);
        return row ? Number(row.total) : 0;
    }
    async getOutboundMessage(messageId) {
        const db = await this.getConnection();
        const row = db.get(`SELECT
                message_id,
                to_jid,
                replay_mode,
                replay_payload,
                requesters_json,
                state,
                updated_at_ms,
                expires_at_ms
            FROM retry_outbound_messages
            WHERE session_id = ? AND message_id = ?`, [this.options.sessionId, messageId]);
        if (!row) {
            return null;
        }
        const requestersJson = asOptionalString(row.requesters_json, 'retry_outbound_messages.requesters_json');
        const requesters = requestersJson
            ? this.parseRequesterStatusPayload(requestersJson)
            : {
                eligible: [],
                delivered: []
            };
        return {
            messageId: asString(row.message_id, 'retry_outbound_messages.message_id'),
            toJid: asString(row.to_jid, 'retry_outbound_messages.to_jid'),
            eligibleRequesterDeviceJids: requesters.eligible.length > 0 ? requesters.eligible : undefined,
            deliveredRequesterDeviceJids: requesters.delivered.length > 0 ? requesters.delivered : undefined,
            replayMode: asString(row.replay_mode, 'retry_outbound_messages.replay_mode'),
            replayPayload: asBytes(row.replay_payload, 'retry_outbound_messages.replay_payload'),
            state: asString(row.state, 'retry_outbound_messages.state'),
            updatedAtMs: asNumber(row.updated_at_ms, 'retry_outbound_messages.updated_at_ms'),
            expiresAtMs: asNumber(row.expires_at_ms, 'retry_outbound_messages.expires_at_ms')
        };
    }
    async updateOutboundMessageState(messageId, state, updatedAtMs, expiresAtMs) {
        const db = await this.getConnection();
        db.run(`UPDATE retry_outbound_messages
             SET state = ?, updated_at_ms = ?, expires_at_ms = ?
             WHERE session_id = ? AND message_id = ?`, [state, updatedAtMs, expiresAtMs, this.options.sessionId, messageId]);
    }
    async markOutboundRequesterDelivered(messageId, requesterDeviceJid, updatedAtMs, expiresAtMs) {
        await this.withTransaction((db) => {
            const row = db.get(`SELECT requesters_json
                 FROM retry_outbound_messages
                 WHERE session_id = ? AND message_id = ?
                 LIMIT 1`, [this.options.sessionId, messageId]);
            if (!row) {
                return;
            }
            const requestersJson = asOptionalString(row.requesters_json, 'retry_outbound_messages.requesters_json');
            if (!requestersJson) {
                return;
            }
            const requesters = this.parseRequesterStatusPayload(requestersJson);
            let isEligible = false;
            for (let index = 0; index < requesters.eligible.length; index += 1) {
                if (requesters.eligible[index] === requesterDeviceJid) {
                    isEligible = true;
                    break;
                }
            }
            if (!isEligible) {
                return;
            }
            for (let index = 0; index < requesters.delivered.length; index += 1) {
                if (requesters.delivered[index] === requesterDeviceJid) {
                    return;
                }
            }
            const nextRequestersJson = this.serializeRequesterStatusPayload(requesters.eligible, [
                ...requesters.delivered,
                requesterDeviceJid
            ]);
            db.run(`UPDATE retry_outbound_messages
                 SET requesters_json = ?, updated_at_ms = ?, expires_at_ms = ?
                 WHERE session_id = ? AND message_id = ?`, [nextRequestersJson, updatedAtMs, expiresAtMs, this.options.sessionId, messageId]);
        });
    }
    async incrementInboundCounter(messageId, requesterJid, _updatedAtMs, expiresAtMs) {
        const db = await this.getConnection();
        const row = db.get(`INSERT INTO retry_inbound_counters (
                session_id,
                message_id,
                requester_jid,
                retry_count,
                expires_at_ms
            ) VALUES (?, ?, ?, 1, ?)
            ON CONFLICT(session_id, message_id, requester_jid) DO UPDATE SET
                retry_count=retry_inbound_counters.retry_count + 1,
                expires_at_ms=excluded.expires_at_ms
            RETURNING retry_count`, [this.options.sessionId, messageId, requesterJid, expiresAtMs]);
        if (!row) {
            return 1;
        }
        return asNumber(row.retry_count, 'retry_inbound_counters.retry_count');
    }
    async cleanupExpired(nowMs) {
        return this.withTransaction((db) => {
            db.run(`DELETE FROM retry_outbound_messages
                 WHERE session_id = ? AND expires_at_ms <= ?`, [this.options.sessionId, nowMs]);
            const outboundCountRow = db.get('SELECT changes() AS total', []);
            const outboundCount = outboundCountRow
                ? asNumber(outboundCountRow.total, 'retry_outbound_messages.changes')
                : 0;
            db.run(`DELETE FROM retry_inbound_counters
                 WHERE session_id = ? AND expires_at_ms <= ?`, [this.options.sessionId, nowMs]);
            const inboundCountRow = db.get('SELECT changes() AS total', []);
            const inboundCount = inboundCountRow
                ? asNumber(inboundCountRow.total, 'retry_inbound_counters.changes')
                : 0;
            return outboundCount + inboundCount;
        });
    }
    async clear() {
        await this.withTransaction((db) => {
            db.run('DELETE FROM retry_outbound_messages WHERE session_id = ?', [
                this.options.sessionId
            ]);
            db.run('DELETE FROM retry_inbound_counters WHERE session_id = ?', [
                this.options.sessionId
            ]);
        });
    }
    serializeRequesterStatusPayload(eligibleRequesterDeviceJids, deliveredRequesterDeviceJids) {
        const eligible = this.toUniqueStrings(eligibleRequesterDeviceJids ?? [], 'requesters_json.eligible');
        if (eligible.length === 0) {
            return null;
        }
        const eligibleSet = new Set(eligible);
        const delivered = this.toUniqueStrings(deliveredRequesterDeviceJids ?? [], 'requesters_json.delivered').filter((jid) => eligibleSet.has(jid));
        const payload = delivered.length > 0
            ? {
                eligible,
                delivered
            }
            : {
                eligible
            };
        return JSON.stringify(payload);
    }
    parseRequesterStatusPayload(raw) {
        const parsed = JSON.parse(raw);
        if (!isObjectRecord(parsed)) {
            throw new Error('retry_outbound_messages.requesters_json must be an object');
        }
        const eligibleRaw = parsed.eligible;
        if (!Array.isArray(eligibleRaw)) {
            throw new Error('retry_outbound_messages.requesters_json.eligible must be an array');
        }
        const eligible = this.toUniqueStrings(eligibleRaw, 'requesters_json.eligible');
        const deliveredRaw = parsed.delivered;
        if (deliveredRaw !== undefined && !Array.isArray(deliveredRaw)) {
            throw new Error('retry_outbound_messages.requesters_json.delivered must be an array');
        }
        const eligibleSet = new Set(eligible);
        const delivered = this.toUniqueStrings(Array.isArray(deliveredRaw) ? deliveredRaw : [], 'requesters_json.delivered').filter((jid) => eligibleSet.has(jid));
        return {
            eligible,
            delivered
        };
    }
    toUniqueStrings(values, field) {
        const deduped = new Set();
        for (let index = 0; index < values.length; index += 1) {
            const rawValue = values[index];
            if (typeof rawValue !== 'string') {
                throw new Error(`${field} must contain only strings`);
            }
            const normalized = rawValue.trim();
            if (!normalized) {
                continue;
            }
            deduped.add(normalized);
        }
        return Array.from(deduped);
    }
}
